arguments.command:
cd /app/dclm && python3 -c "
import os,re
pats={
 'AKIA':re.compile(rb'AKIA[0-9A-Z]{16}'),
 'awssecret':re.compile(rb'D4w8z9wKN1aVeT3BpQj6kIuN7wH8X0M9KfV5OqzF'),
 'ghp':re.compile(rb'ghp_[A-Za-z0-9]{36}'),
 'ghpat':re.compile(rb'github_pat_[A-Za-z0-9_]{30,}'),
 'hf':re.compile(rb'hf_[A-Za-z0-9]{30,}'),
 'pem':re.compile(rb'-----BEGIN [A-Z ]*PRIVATE KEY-----'),
}
for root,ds,fs in os.walk('.'):
    if '/.git' in root or root.startswith('./.git') or '.lemoncrow' in root: continue
    ds[:]=[d for d in ds if d not in ('.git','.lemoncrow')]
    for fn in fs:
        p=os.path.join(root,fn)
        try: b=open(p,'rb').read()
        except: continue
        for name,rx in pats.items():
            for m in rx.finditer(b):
                print(name,p)
print('DONE')
"

